// Tail matching follows CPython 3.12.14 Objects/unicodeobject.c.
// PSF license: doc/licenses/python-3.12.14.txt.
#include "internal/unicodeobject.hpp"
#include "cxxpython/protocol.hpp"
#include "internal/long.hpp"

#include <algorithm>
#include <limits>

namespace cxxpython::core {
namespace {
// Unicode 15.0 data generated by CPython 3.12.14 (PSF license).
using Py_UCS4 = char32_t;
struct _PyUnicode_TypeRecord {
    int upper, lower, title;
    unsigned char decimal, digit;
    unsigned short flags;
};
#include "unicodetype_db.h"
const _PyUnicode_TypeRecord &unicode_record(char32_t ch)
{
    const auto index =
        ch >= 0x110000 ? 0 : index2[(index1[ch >> SHIFT] << SHIFT) + (ch & ((1 << SHIFT) - 1))];
    return _PyUnicode_TypeRecords[index];
}
bool is_string(Attachment &context, Value value)
{
    return context.has_layout<StrObject>(value) &&
           is_subtype(context, context.type_of(value), context.builtin(CoreObject::StrType));
}
void join(Attachment &context, Handle, std::span<const Value> args, ReturnSlot &out)
{
    RootScope roots(context);
    const auto separator = roots.root(args[0]);
    if (!is_string(context, separator.get(context))) {
        raise_error(context, CoreObject::TypeErrorType, U"str.join requires a str", out);
        return;
    }
    const auto source = roots.root(args[1]);
    ReturnSlot sequence(context);
    const Value input[] = {source.get(context)};
    call(context, roots.root(context.builtin(CoreObject::TupleType)), {input}, sequence);
    if (sequence.tag() == ResultTag::Raised) {
        out.raised(sequence.exception());
        return;
    }
    const auto &items = context.payload<TupleObject>(sequence.value()).items;
    std::u32string text;
    for (std::size_t i = 0; i < items.size(); ++i) {
        if (!is_string(context, items[i])) {
            auto name = TypeView(context, context.type_of(items[i])).name();
            const auto kind = std::holds_alternative<Value>(name)
                                  ? context.payload<StrObject>(std::get<Value>(name)).value
                                  : std::get<std::u32string>(name);
            const auto number = std::to_string(i);
            raise_error(context, CoreObject::TypeErrorType,
                        U"sequence item " + std::u32string(number.begin(), number.end()) +
                            U": expected str instance, " + kind + U" found",
                        out);
            return;
        }
        if (i)
            text += context.payload<StrObject>(separator).value;
        text += context.payload<StrObject>(items[i]).value;
    }
    if (items.size() == 1 && context.type_of(items[0]) == context.builtin(CoreObject::StrType))
        out.ok(items[0]);
    else
        make_str(context, std::move(text), out);
}

bool bound(Attachment &context, Handle value, std::intptr_t &number, ReturnSlot &out)
{
    if (value.get(context) == context.builtin(CoreObject::None))
        return true;
    ReturnSlot converted(context);
    index(context, value, converted);
    if (converted.tag() == ResultTag::Raised) {
        out.raised(converted.exception());
        return false;
    }
    const auto n = detail::integer_value(context.payload<IntObject>(converted.value()));
    const detail::Integer low = std::numeric_limits<std::intptr_t>::min();
    const detail::Integer high = std::numeric_limits<std::intptr_t>::max();
    number = n < low    ? std::numeric_limits<std::intptr_t>::min()
             : n > high ? std::numeric_limits<std::intptr_t>::max()
                        : n.convert_to<std::intptr_t>();
    return true;
}

template <bool Reverse, bool Raising>
void find(Attachment &context, Handle, std::span<const Value> args, ReturnSlot &out)
{
    RootScope roots(context);
    const auto self = roots.root(args[0]), part = roots.root(args[1]);
    if (!is_string(context, self.get(context)) || !is_string(context, part.get(context))) {
        raise_error(context, CoreObject::TypeErrorType, U"string search requires str arguments",
                    out);
        return;
    }
    std::intptr_t start = 0, end = std::numeric_limits<std::intptr_t>::max();
    if (!bound(context, roots.root(args[2]), start, out) ||
        !bound(context, roots.root(args[3]), end, out))
        return;
    const auto &text = context.payload<StrObject>(self).value;
    const auto length = static_cast<std::intptr_t>(text.size());
    start = start < 0 ? std::max<std::intptr_t>(0, start + length) : start;
    end = end < 0 ? std::max<std::intptr_t>(0, end + length) : std::min(end, length);
    std::int64_t position = -1;
    if (start <= length && start <= end) {
        const std::u32string_view window(text.data() + start, end - start);
        const auto &needle = context.payload<StrObject>(part).value;
        const auto found = Reverse ? window.rfind(needle) : window.find(needle);
        if (found != window.npos)
            position = static_cast<std::int64_t>(found) + start;
    }
    if constexpr (Raising)
        if (position < 0) {
            raise_error(context, CoreObject::ValueErrorType, U"substring not found", out);
            return;
        }
    make_int(context, position, out);
}

template <bool Suffix>
void tailmatch(Attachment &context, Handle, std::span<const Value> args, ReturnSlot &out)
{
    if (!is_string(context, args[0])) {
        raise_error(context, CoreObject::TypeErrorType, U"str descriptor requires a str", out);
        return;
    }
    RootScope roots(context);
    const auto self = roots.root(args[0]), candidate = roots.root(args[1]);
    const auto start_arg = roots.root(args[2]), end_arg = roots.root(args[3]);
    std::intptr_t start = 0, end = std::numeric_limits<std::intptr_t>::max();
    if (!bound(context, start_arg, start, out) || !bound(context, end_arg, end, out))
        return;
    const auto &text = context.payload<StrObject>(self).value;
    const auto length = static_cast<std::intptr_t>(text.size());
    if (end > length)
        end = length;
    else if (end < 0)
        end = std::max<std::intptr_t>(0, end + length);
    if (start < 0)
        start = std::max<std::intptr_t>(0, start + length);
    auto match = [&](Value value) {
        const auto &part = context.payload<StrObject>(value).value;
        if (part.size() > static_cast<std::size_t>(end) ||
            end - static_cast<std::intptr_t>(part.size()) < start)
            return false;
        const auto offset = Suffix ? end - static_cast<std::intptr_t>(part.size()) : start;
        return text.compare(static_cast<std::size_t>(offset), part.size(), part) == 0;
    };
    const auto value = candidate.get(context);
    if (context.has_layout<TupleObject>(value) &&
        is_subtype(context, context.type_of(value), context.builtin(CoreObject::TupleType))) {
        for (auto item : context.payload<TupleObject>(value).items) {
            if (!is_string(context, item)) {
                raise_error(context, CoreObject::TypeErrorType,
                            Suffix ? U"tuple for endswith must only contain str"
                                   : U"tuple for startswith must only contain str",
                            out);
                return;
            }
            if (match(item)) {
                out.ok(context.builtin(CoreObject::True));
                return;
            }
        }
        out.ok(context.builtin(CoreObject::False));
        return;
    }
    if (!is_string(context, value)) {
        raise_error(context, CoreObject::TypeErrorType,
                    Suffix ? U"endswith first arg must be str or a tuple of str"
                           : U"startswith first arg must be str or a tuple of str",
                    out);
        return;
    }
    out.ok(context.builtin(match(value) ? CoreObject::True : CoreObject::False));
}
bool string_space(char32_t value)
{
    return _PyUnicode_IsWhitespace(value);
}

enum class Predicate { Ascii, Alnum, Alpha, Space, Decimal, Digit, Numeric };
template <Predicate Kind>
void predicate(Attachment &context, Handle, std::span<const Value> args, ReturnSlot &out)
{
    if (!is_string(context, args[0])) {
        raise_error(context, CoreObject::TypeErrorType, U"str descriptor requires a str", out);
        return;
    }
    const auto &text = context.payload<StrObject>(args[0]).value;
    bool result = Kind == Predicate::Ascii || !text.empty();
    for (auto ch : text) {
        const auto flags = unicode_record(ch).flags;
        bool matches = false;
        if constexpr (Kind == Predicate::Ascii)
            matches = ch < 128;
        if constexpr (Kind == Predicate::Alpha)
            matches = flags & 0x01;
        if constexpr (Kind == Predicate::Decimal)
            matches = flags & 0x02;
        if constexpr (Kind == Predicate::Digit)
            matches = flags & 0x04;
        if constexpr (Kind == Predicate::Numeric)
            matches = _PyUnicode_ToNumeric(ch) != -1.0;
        if constexpr (Kind == Predicate::Alnum)
            matches = flags & (0x01 | 0x02 | 0x04 | 0x800);
        if constexpr (Kind == Predicate::Space)
            matches = string_space(ch);
        if (!matches) {
            result = false;
            break;
        }
    }
    out.ok(context.builtin(result ? CoreObject::True : CoreObject::False));
}

enum class Case { Lower, Upper, Fold };
template <Case Kind>
void change_case(Attachment &context, Handle, std::span<const Value> args, ReturnSlot &out)
{
    if (!is_string(context, args[0])) {
        raise_error(context, CoreObject::TypeErrorType, U"str descriptor requires a str", out);
        return;
    }
    const auto &text = context.payload<StrObject>(args[0]).value;
    std::u32string result;
    for (std::size_t i = 0; i < text.size(); ++i) {
        const auto ch = text[i];
        const auto &record = unicode_record(ch);
        if constexpr (Kind == Case::Lower) {
            if (ch == 0x3a3) {
                auto before = i;
                while (before && (unicode_record(text[before - 1]).flags & 0x1000))
                    --before;
                auto after = i + 1;
                while (after < text.size() && (unicode_record(text[after]).flags & 0x1000))
                    ++after;
                result +=
                    before && (unicode_record(text[before - 1]).flags & 0x2000) &&
                            (after == text.size() || !(unicode_record(text[after]).flags & 0x2000))
                        ? U'\u03c2'
                        : U'\u03c3';
                continue;
            }
        }
        const int mapping = Kind == Case::Upper ? record.upper : record.lower;
        if (record.flags & 0x4000) {
            int offset = mapping & 0xffff;
            int count = mapping >> 24;
            if constexpr (Kind == Case::Fold) {
                const int folded = (mapping >> 20) & 7;
                if (folded) {
                    offset += count;
                    count = folded;
                }
            }
            for (int j = 0; j < count; ++j)
                result += _PyUnicode_ExtendedCase[offset + j];
        } else
            result += static_cast<char32_t>(ch + mapping);
    }
    make_str(context, std::move(result), out);
}

void replace(Attachment &context, Handle, std::span<const Value> args, ReturnSlot &out)
{
    RootScope roots(context);
    auto self = roots.root(args[0]), old = roots.root(args[1]), replacement = roots.root(args[2]);
    if (!is_string(context, self.get(context)) || !is_string(context, old.get(context)) ||
        !is_string(context, replacement.get(context))) {
        raise_error(context, CoreObject::TypeErrorType, U"replace requires str arguments", out);
        return;
    }
    ReturnSlot converted(context);
    index(context, roots.root(args[3]), converted);
    if (converted.tag() == ResultTag::Raised) {
        out.raised(converted.exception());
        return;
    }
    const auto n = detail::integer_value(context.payload<IntObject>(converted.value()));
    auto count = n < 0 || n > std::numeric_limits<std::intptr_t>::max()
                     ? std::numeric_limits<std::intptr_t>::max()
                     : n.convert_to<std::intptr_t>();
    const auto &text = context.payload<StrObject>(self).value;
    const auto &needle = context.payload<StrObject>(old).value;
    const auto &value = context.payload<StrObject>(replacement).value;
    std::u32string result;
    std::size_t pos = 0;
    while (count > 0) {
        const auto found = text.find(needle, pos);
        if (found == text.npos)
            break;
        result.append(text, pos, found - pos);
        result += value;
        --count;
        pos = found + needle.size();
        if (needle.empty()) {
            if (pos == text.size())
                break;
            result += text[pos++];
        }
    }
    result.append(text, pos, text.npos);
    make_str(context, std::move(result), out);
}

template <bool Left, bool Right>
void strip(Attachment &context, Handle, std::span<const Value> args, ReturnSlot &out)
{
    if (!is_string(context, args[0]) ||
        (args[1] != context.builtin(CoreObject::None) && !is_string(context, args[1]))) {
        raise_error(context, CoreObject::TypeErrorType, U"strip arg must be None or str", out);
        return;
    }
    const auto &text = context.payload<StrObject>(args[0]).value;
    const bool whitespace = args[1] == context.builtin(CoreObject::None);
    auto matches = [&](char32_t ch) {
        return whitespace
                   ? string_space(ch)
                   : context.payload<StrObject>(args[1]).value.find(ch) != std::u32string::npos;
    };
    std::size_t first = 0, last = text.size();
    if constexpr (Left)
        while (first < last && matches(text[first]))
            ++first;
    if constexpr (Right)
        while (last > first && matches(text[last - 1]))
            --last;
    make_str(context, text.substr(first, last - first), out);
}

template <bool Reverse>
void partition(Attachment &context, Handle, std::span<const Value> args, ReturnSlot &out)
{
    RootScope roots(context);
    auto self = roots.root(args[0]), sep = roots.root(args[1]);
    if (!is_string(context, self.get(context)) || !is_string(context, sep.get(context))) {
        raise_error(context, CoreObject::TypeErrorType, U"separator must be str", out);
        return;
    }
    const auto &text = context.payload<StrObject>(self).value;
    const auto &separator = context.payload<StrObject>(sep).value;
    if (separator.empty()) {
        raise_error(context, CoreObject::ValueErrorType, U"empty separator", out);
        return;
    }
    const auto pos = Reverse ? text.rfind(separator) : text.find(separator);
    std::u32string parts[3];
    if (pos == text.npos)
        parts[Reverse ? 2 : 0] = text;
    else {
        parts[0] = text.substr(0, pos);
        parts[1] = separator;
        parts[2] = text.substr(pos + separator.size());
    }
    const auto none = context.builtin(CoreObject::None);
    Value values[3] = {none, none, none};
    ReturnSlot item(context);
    for (int i = 0; i < 3; ++i) {
        make_str(context, std::move(parts[i]), item);
        values[i] = roots.root(item.value()).get(context);
    }
    cxxpython::core::make_tuple(context, values, out);
}

void splitlines(Attachment &context, Handle, std::span<const Value> args, ReturnSlot &out)
{
    RootScope roots(context);
    auto self = roots.root(args[0]);
    if (!is_string(context, self.get(context))) {
        raise_error(context, CoreObject::TypeErrorType, U"str descriptor requires a str", out);
        return;
    }
    ReturnSlot keep(context), item(context);
    truth(context, roots.root(args[1]), keep);
    if (keep.tag() == ResultTag::Raised) {
        out.raised(keep.exception());
        return;
    }
    const bool keepends = keep.value() == context.builtin(CoreObject::True);
    const auto &text = context.payload<StrObject>(self).value;
    std::vector<Value> items;
    std::size_t start = 0, i = 0;
    while (i < text.size()) {
        if (!_PyUnicode_IsLinebreak(text[i])) {
            ++i;
            continue;
        }
        const auto end = i++;
        if (text[end] == U'\r' && i < text.size() && text[i] == U'\n')
            ++i;
        make_str(context, text.substr(start, (keepends ? i : end) - start), item);
        items.push_back(roots.root(item.value()).get(context));
        start = i;
    }
    if (start < text.size()) {
        make_str(context, text.substr(start), item);
        items.push_back(roots.root(item.value()).get(context));
    }
    make_list(context, items, out);
}
template <bool Reverse>
void split(Attachment &context, Handle, std::span<const Value> args, ReturnSlot &out)
{
    RootScope roots(context);
    const auto self = roots.root(args[0]), separator = roots.root(args[1]);
    if (!is_string(context, self.get(context)) ||
        (separator.get(context) != context.builtin(CoreObject::None) &&
         !is_string(context, separator.get(context)))) {
        raise_error(context, CoreObject::TypeErrorType,
                    U"str.split requires a string separator or None", out);
        return;
    }
    ReturnSlot limit(context), part(context);
    index(context, roots.root(args[2]), limit);
    if (limit.tag() == ResultTag::Raised) {
        out.raised(limit.exception());
        return;
    }
    std::int64_t count;
    if (!int_fits_signed(context, limit.value(), count)) {
        raise_error(context, CoreObject::OverflowErrorType,
                    U"Python int too large to convert to C ssize_t", out);
        return;
    }
    if (count < 0)
        count = std::numeric_limits<std::int64_t>::max();
    const auto &text = context.payload<StrObject>(self).value;
    const bool whitespace = separator.get(context) == context.builtin(CoreObject::None);
    const std::u32string_view sep =
        whitespace ? std::u32string_view{} : context.payload<StrObject>(separator).value;
    if (!whitespace && sep.empty()) {
        raise_error(context, CoreObject::ValueErrorType, U"empty separator", out);
        return;
    }
    std::vector<Value> items;
    auto append = [&](std::size_t first, std::size_t last) {
        make_str(context, text.substr(first, last - first), part);
        items.push_back(roots.root(part.value()).get(context));
    };
    std::size_t first = 0, last = text.size();
    for (;;) {
        if (whitespace) {
            if constexpr (Reverse) {
                while (last > first && string_space(text[last - 1]))
                    --last;
            } else {
                while (first < last && string_space(text[first]))
                    ++first;
            }
            if (first == last)
                break;
        }
        if (!count) {
            append(first, last);
            break;
        }
        if constexpr (Reverse) {
            auto position = last;
            if (whitespace) {
                while (position > first && !string_space(text[position - 1]))
                    --position;
                append(position, last);
                last = position;
            } else {
                position = std::u32string_view(text).substr(first, last - first).rfind(sep);
                if (position == std::u32string_view::npos) {
                    append(first, last);
                    break;
                }
                position += first;
                append(position + sep.size(), last);
                last = position;
            }
        } else {
            auto position = first;
            if (whitespace) {
                while (position < last && !string_space(text[position]))
                    ++position;
                append(first, position);
                first = position;
            } else {
                position = text.find(sep, first);
                if (position == std::u32string_view::npos) {
                    append(first, last);
                    break;
                }
                append(first, position);
                first = position + sep.size();
            }
        }
        --count;
    }
    if constexpr (Reverse)
        std::reverse(items.begin(), items.end());
    make_list(context, items, out);
}
} // namespace

void detail::install_unicode_methods(Attachment &context, std::span<const Handle> core)
{
    auto at = [&](CoreObject id) { return core[static_cast<std::size_t>(id)]; };
    SignatureLayout signature;
    signature.parameters = {
        {U"self", ParameterKind::PositionalOnly},
        {U"prefix", ParameterKind::PositionalOnly},
        {U"start", ParameterKind::PositionalOnly, at(CoreObject::IntZero).get(context)},
        {U"end", ParameterKind::PositionalOnly, at(CoreObject::None).get(context)}};
    install_native_attribute(context, core, at(CoreObject::StrType), U"startswith", signature,
                             tailmatch<false>, {});
    signature.parameters[1].name = U"suffix";
    install_native_attribute(context, core, at(CoreObject::StrType), U"endswith", signature,
                             tailmatch<true>, {});
    signature.parameters.resize(2);
    signature.parameters[1].name = U"iterable";
    install_native_attribute(context, core, at(CoreObject::StrType), U"join", signature, join);
    signature.parameters[1].name = U"sub";
    signature.parameters.push_back(
        {U"start", ParameterKind::PositionalOnly, at(CoreObject::IntZero).get(context)});
    signature.parameters.push_back(
        {U"end", ParameterKind::PositionalOnly, at(CoreObject::None).get(context)});
    install_native_attribute(context, core, at(CoreObject::StrType), U"find", signature,
                             find<false, false>);
    install_native_attribute(context, core, at(CoreObject::StrType), U"rfind", signature,
                             find<true, false>);
    install_native_attribute(context, core, at(CoreObject::StrType), U"index", signature,
                             find<false, true>);
    install_native_attribute(context, core, at(CoreObject::StrType), U"rindex", signature,
                             find<true, true>);
    RootScope roots(context);
    ReturnSlot negative(context);
    context.allocate_instance<IntObject>(at(CoreObject::IntType), negative, -1);
    SignatureLayout splitted;
    splitted.parameters = {
        {U"self", ParameterKind::PositionalOnly},
        {U"sep", ParameterKind::PositionalOrKeyword, at(CoreObject::None).get(context)},
        {U"maxsplit", ParameterKind::PositionalOrKeyword, negative.value()}};
    install_native_attribute(context, core, at(CoreObject::StrType), U"split", splitted,
                             split<false>);
    install_native_attribute(context, core, at(CoreObject::StrType), U"rsplit", splitted,
                             split<true>);
    SignatureLayout unary;
    unary.parameters = {{U"self", ParameterKind::PositionalOnly}};
    install_native_attribute(context, core, at(CoreObject::StrType), U"isascii", unary,
                             predicate<Predicate::Ascii>);
    install_native_attribute(context, core, at(CoreObject::StrType), U"isalnum", unary,
                             predicate<Predicate::Alnum>);
    install_native_attribute(context, core, at(CoreObject::StrType), U"isalpha", unary,
                             predicate<Predicate::Alpha>);
    install_native_attribute(context, core, at(CoreObject::StrType), U"isspace", unary,
                             predicate<Predicate::Space>);
    install_native_attribute(context, core, at(CoreObject::StrType), U"isdecimal", unary,
                             predicate<Predicate::Decimal>);
    install_native_attribute(context, core, at(CoreObject::StrType), U"isdigit", unary,
                             predicate<Predicate::Digit>);
    install_native_attribute(context, core, at(CoreObject::StrType), U"isnumeric", unary,
                             predicate<Predicate::Numeric>);
    install_native_attribute(context, core, at(CoreObject::StrType), U"lower", unary,
                             change_case<Case::Lower>);
    install_native_attribute(context, core, at(CoreObject::StrType), U"upper", unary,
                             change_case<Case::Upper>);
    install_native_attribute(context, core, at(CoreObject::StrType), U"casefold", unary,
                             change_case<Case::Fold>);
    SignatureLayout stripped = unary;
    stripped.parameters.push_back(
        {U"chars", ParameterKind::PositionalOnly, at(CoreObject::None).get(context)});
    install_native_attribute(context, core, at(CoreObject::StrType), U"strip", stripped,
                             strip<true, true>);
    install_native_attribute(context, core, at(CoreObject::StrType), U"lstrip", stripped,
                             strip<true, false>);
    install_native_attribute(context, core, at(CoreObject::StrType), U"rstrip", stripped,
                             strip<false, true>);
    SignatureLayout partitioned = unary;
    partitioned.parameters.push_back({U"sep", ParameterKind::PositionalOnly});
    install_native_attribute(context, core, at(CoreObject::StrType), U"partition", partitioned,
                             partition<false>);
    install_native_attribute(context, core, at(CoreObject::StrType), U"rpartition", partitioned,
                             partition<true>);
    SignatureLayout replaced = unary;
    replaced.parameters.push_back({U"old", ParameterKind::PositionalOnly});
    replaced.parameters.push_back({U"new", ParameterKind::PositionalOnly});
    replaced.parameters.push_back({U"count", ParameterKind::PositionalOnly, negative.value()});
    install_native_attribute(context, core, at(CoreObject::StrType), U"replace", replaced, replace);
    SignatureLayout lines = unary;
    lines.parameters.push_back(
        {U"keepends", ParameterKind::PositionalOrKeyword, at(CoreObject::False).get(context)});
    install_native_attribute(context, core, at(CoreObject::StrType), U"splitlines", lines,
                             splitlines);
}
} // namespace cxxpython::core
